        // Delphi: procedure TFormASCIITransfer.RadioGroupASCIIFilesClick(Sender: TObject)
        public void RadioGroupASCIIFilesClick(object Sender)
        {
            if (fASCIISend != null)
            {
                switch (fASCIISend.Count)
                {
                    case 0:
                        {
                            Rtl.Lines(MemoData).Clear();
                        }
                        break;
                    case 1:
                        {
                            Rtl.Lines(MemoData).LoadFromFile(fASCIISend[0].FileName);
                        }
                        break;
                    default:
                        {
                            Rtl.Lines(MemoData).LoadFromFile(fASCIISend[Rtl.GetItemIndex(RadioGroupASCIIFiles)].FileName);
                        }
                        break;
                }
            }
        }

