        // Delphi: procedure TFormASCIITransfer.TimerGetWhoAMITimer(Sender: TObject)
        public void TimerGetWhoAMITimer(object Sender)
        {
            if (Rtl.GetVisible(this))
            {
                fTicks++;
                Rtl.SetCaption(LabelTicks, Rtl.IntToStr(fTicks) + " ticks");
                Rtl.SetCaption(LabelChars, Rtl.IntToStr(fChars) + " chars");
                Rtl.SetCaption(LabelRecords, Rtl.IntToStr(fRecCount) + " records");
                fTimeOut--;
                if (fTimeOut <= 0)
                {
                    Rtl.SetVisible(imgHourGlass, false);
                    Rtl.SetVisible(LabelWaiting, false);
                    if (fWHORUState != tWHORUState.wru_Timeout)
                    {
                        fWHORUState = tWHORUState.wru_Timeout;
                        TimerGetWhoAMI.Enabled = false;
                        if (UnitRemoteLoginNotSupported.FormRemoteLoginNotSupported.Execute())
                        {
                            fTimeOut = fRepeatTimeOut;
                            TimerGetWhoAMI.Enabled = true;
                            TimerCommon.Enabled = true;
                            return;
                        }
                        else
                        {
                            StopTimers();
                            Rtl.SetModalResult(this, Rtl.mrCancel);
                            return;
                        }
                    }
                    else if (fASCIIExtraInfo.CurrentSendStatus().RetryCount < 3)
                    {
                        RetryCount = RetryCount + 1;
                        if (fASCIIExtraInfo.ResendLastRec())
                        {
                            fTimeOut = fRepeatTimeOut;
                            return;
                        }
                    }
                    fASCIIExtraInfo.Stop();
                    TimerGetWhoAMI.Enabled = false;
                    TimerCommon.Enabled = false;
                    AbortButtonVisible = false;
                    throw new ExceptionZFPTransfer(Translate("Timed out"));
                }
            }
            else
            {
                StopTimers();
            }
        }

