        // Delphi: procedure TFormASCIITransfer.ProcessRcvRec(const pRec: string; const pStatus: tASCIIXIRxObject)
        internal void ProcessRcvRec(string pRec, tASCIIXIRxObject pStatus)
        {
            int iID = 0;
            int iPanel = 0;
            int iChecksum = 0;
            string iText = "";
            if (Rtl.GetVisible(this))
            {
                if (!pStatus.ChecksumOK())
                {
                    if (fASCIIExtraInfo.CurrentSendStatus().RetryCount < 3)
                    {
                        fASCIIExtraInfo.SendNotification("CSFAIL");
                        RetryCount = RetryCount + 1;
                    }
                    else
                    {
                        iText = Translate("Retry Count Exceeded");
                        fErrors.Add(tErrorSeverity.es_Error, 0, 0, iText, null);
                        StopTimers();
                        fASCIIExtraInfo.Stop();
                        throw new ExceptionZFPTransfer(iText);
                    }
                }
                else
                {
                    switch (UnitParseZFPRec.ParseZFPRec(pRec, fList, ref iID, ref iPanel, ref iChecksum))
                    {
                        case tRecvRecType.rrt_ACK or tRecvRecType.rrt_Error or tRecvRecType.rrt_REQUEST:
                            {
                                return;
                            }
                            break;
                        case tRecvRecType.rrt_WAIT:
                            {
                                fTimeOut = iChecksum / (int)TimerRetrieve.Interval;
                                Rtl.SetVisible(imgHourGlass, true);
                                Rtl.SetVisible(LabelWaiting, true);
                                return;
                            }
                            break;
                        case tRecvRecType.rrt_NAK or tRecvRecType.rrt_CSFAIL or tRecvRecType.rrt_TIMEOUT:
                            {
                                if (fASCIIExtraInfo.CurrentSendStatus().RetryCount < 3)
                                {
                                    RetryCount = RetryCount + 1;
                                    fASCIIExtraInfo.ResendLastRec();
                                }
                                else
                                {
                                    iText = Translate("Retry Count Exceeded");
                                    fErrors.Add(tErrorSeverity.es_Error, 0, 0, iText, null);
                                    throw new ExceptionZFPTransfer(iText);
                                }
                            }
                            break;
                        case tRecvRecType.rrt_BEGIN:
                            {
                                Rtl.Lines(MemoRetrieve).Add(pRec);
                                fASCIIExtraInfo.SendNotification("ACK");
                                fASCIIExtraInfo.CurrentSendStatus().RetryCount = 0;
                                fRecCount++;
                                fBeginReceived = true;
                                fTimeOut = fRepeatTimeOut;
                            }
                            break;
                        case tRecvRecType.rrt_Other:
                            {
                                if (fBeginReceived)
                                {
                                    Rtl.Lines(MemoRetrieve).Add(pRec);
                                    fASCIIExtraInfo.SendNotification("ACK");
                                    fASCIIExtraInfo.CurrentSendStatus().RetryCount = 0;
                                    fRecCount++;
                                    fTimeOut = fRepeatTimeOut;
                                }
                            }
                            break;
                        case tRecvRecType.rrt_IAM:
                            {
                                if (!fBeginReceived)
                                {
                                    Rtl.Lines(MemoRetrieve).Add(pRec);
                                    iPanel = Rtl.StrToIntDef(fList[2], -1);
                                    if (fList[4] == "0")
                                    {
                                        fWHORUState = tWHORUState.wru_WrongPIN;
                                    }
                                    else if (fList[4] == "1")
                                    {
                                        fWHORUState = tWHORUState.wru_CorrectPIN;
                                    }
                                    else if (fList[4] == "")
                                    {
                                        fWHORUState = tWHORUState.wru_Blank;
                                    }
                                    else
                                    {
                                        fWHORUState = tWHORUState.wru_WrongPIN;
                                    }
                                    switch (fWHORUState)
                                    {
                                        case tWHORUState.wru_Pending or tWHORUState.wru_Timeout:
                                            {
                                                Rtl.SetModalResult(this, Rtl.mrCancel);
                                                StopTimers();
                                                throw new ExceptionZFP(Translate("Internal Transfer Error 001 - Transfer aborted"));
                                            }
                                            break;
                                        case tWHORUState.wru_WrongPIN:
                                            {
                                                Rtl.SetModalResult(this, Rtl.mrCancel);
                                                StopTimers();
                                                throw new ExceptionZFPTransfer(Translate("Wrong PIN - Transfer aborted"));
                                            }
                                            break;
                                        case tWHORUState.wru_Blank or tWHORUState.wru_CorrectPIN:
                                            {
                                            }
                                            break;
                                    }
                                    if (Rtl.StrToIntDef(fList[2], -1) == fPanel)
                                    {
                                        SendNextRcvRec();
                                        fASCIIExtraInfo.CurrentSendStatus().RetryCount = 0;
                                        fRecCount++;
                                        fTimeOut = fRepeatTimeOut;
                                    }
                                    else if (UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Allow_Cfg_from_remote_panels))
                                    {
                                        SendNextRcvRec();
                                        fASCIIExtraInfo.CurrentSendStatus().RetryCount = 0;
                                        fRecCount++;
                                        fTimeOut = fRepeatTimeOut;
                                    }
                                    else
                                    {
                                        iText = Translate("Wrong panel") + " (" + fList[2] + ") " + Translate("Detected");
                                        fErrors.Add(tErrorSeverity.es_Error, 0, 0, iText, null);
                                        throw new ExceptionZFP(iText);
                                    }
                                }
                            }
                            break;
                        case tRecvRecType.rrt_END:
                            {
                                if (fBeginReceived)
                                {
                                    Rtl.Lines(MemoRetrieve).Add(pRec);
                                    SendNextRcvRec();
                                    fASCIIExtraInfo.CurrentSendStatus().RetryCount = 0;
                                    fBeginReceived = false;
                                    fRecCount++;
                                    fTimeOut = fRepeatTimeOut;
                                }
                            }
                            break;
                    }
                }
            }
        }

