        // Delphi: procedure TFormASCIITransfer.SetAbortButtonVisible(const Value: boolean)
        internal void SetAbortButtonVisible(bool Value)
        {
            if (Rtl.GetVisible(BitBtnAbortXFER) != Value)
            {
                Rtl.SetVisible(BitBtnAbortXFER, Value);
                if (Value)
                {
                    Rtl.SetEnabled(BitBtnAbortXFER, false);
                    TimerEnableAbort.Enabled = true;
                }
                else
                {
                    StopTimers();
                }
            }
        }

        // Delphi: procedure TFormASCIITransfer.CheckForDevices
        public void CheckForDevices()
        {
            int i = 0;
            int iCount = 0;
            Rtl.Items(RadioGroupDevicesConnected).Clear();
            Rtl.SetVisible(LabelNoDevicesFound, false);
            iCount = fASCIIExtraInfo.CheckForDevices();
            for (i = 0; i <= iCount - 1; i++)
            {
                Rtl.Items(RadioGroupDevicesConnected).Add(fASCIIExtraInfo.GetConnectionName(i));
            }
            if (iCount > 0)
            {
                Rtl.SetItemIndex(RadioGroupDevicesConnected, 0);
                fASCIIExtraInfo.ActivePortIndex = Rtl.GetItemIndex(RadioGroupDevicesConnected);
            }
            else
            {
                Rtl.SetVisible(LabelNoDevicesFound, true);
                fASCIIExtraInfo.ActivePortIndex = -1;
            }
        }

        // Delphi: procedure TFormASCIITransfer.SetupRadioGroupASCIIFiles
        public void SetupRadioGroupASCIIFiles()
        {
            int i = 0;
            string iName = "";
            if (fASCIISend != null)
            {
                if (fASCIISend.Count < 1)
                {
                    Rtl.SetVisible(RadioGroupASCIIFiles, false);
                }
                else
                {
                    Rtl.SetVisible(RadioGroupASCIIFiles, true);
                    Rtl.Items(RadioGroupASCIIFiles).Clear();
                    Rtl.Items(CheckListBoxToSend).Clear();
                    {
                        int __end1 = fASCIISend.Count - 1; // Delphi evaluates the loop bound once
                        for (i = 0; i <= __end1; i++)
                        {
                            iName = Rtl.ExtractFileName(fASCIISend[i].FileName);
                            Rtl.Items(CheckListBoxToSend).Add(iName);
                            Rtl.Items(RadioGroupASCIIFiles).Add(iName);
                            Rtl.CheckList(CheckListBoxToSend)[i] = true;
                        }
                    }
                    Rtl.SetItemIndex(RadioGroupASCIIFiles, 0);
                }
            }
            else
            {
                Rtl.SetVisible(RadioGroupASCIIFiles, false);
            }
            RadioGroupASCIIFilesClick(this);
        }

        // Delphi: procedure TFormASCIITransfer.SetupCheckboxesRetrieveASCIIFiles(pChecked: boolean)
        public void SetupCheckboxesRetrieveASCIIFiles(bool pChecked)
        {
            int i = 0;
            Rtl.Items(RadioGroupASCIIFiles).Clear();
            Rtl.ClearControl(MemoRetrieve);
            Rtl.ClearControl(CheckListBoxToRetrieve);
            {
                int __end1 = fASCIIRequests.Count - 1; // Delphi evaluates the loop bound once
                for (i = 0; i <= __end1; i++)
                {
                    {
                        // with CheckListBoxToRetrieve do
                        Rtl.CheckList(CheckListBoxToRetrieve)[Rtl.Items(CheckListBoxToRetrieve).AddObject(Rtl.ExtractFileName(fASCIIRequests[i].FileName), fASCIIRequests[i])] = pChecked;
                    }
                }
            }
        }

