        // Delphi: procedure TFormASCIITransfer.ExportASCIIFile(const pBaseName: string; const pPanelIndex: integer; const pDataName: string; const pCSVData: tStrings)
        public void ExportASCIIFile(string pBaseName, int pPanelIndex, string pDataName, TStrings pCSVData)
        {
            string pFileName = "";
            pFileName = Rtl.ChangeFileExt(pBaseName, "");
            pFileName = pFileName + "(" + Rtl.IntToStr(pPanelIndex) + ")" + pDataName + ".csv";
            pCSVData.SaveToFile(pFileName);
            fASCIISend.Add(pFileName, "");
        }

        // Delphi: procedure TFormASCIITransfer.ImportASCIIFile(const pBaseName: string; const pPanelIndex: integer; const pDataName: string; const pCSVReq: string)
        public void ImportASCIIFile(string pBaseName, int pPanelIndex, string pDataName, string pCSVReq)
        {
            string pFileName = "";
            if (pBaseName != "")
            {
                pFileName = Rtl.ChangeFileExt(pBaseName, "");
                pFileName = pFileName + " Rcv(" + Rtl.IntToStr(pPanelIndex) + ")" + pDataName + ".csv";
            }
            fASCIIRequests.Add(pFileName, pCSVReq);
        }

