        // Delphi: procedure TFormASCIITransfer.AskWhoAreYou
        public void AskWhoAreYou()
        {
            RetryCount = 0;
            fErrors.Clear();
            fRecCount = 0;
            fASCIIExtraInfo.UseWaitForSingleObject = UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Check_USB_Status);
            fASCIIExtraInfo.UseThreading = UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Use_Threading);
            ClearASCIISendFileList();
            fWHORUFile.Clear();
            fWHORUFile.Add("200,WHORU,0," + UnitPanelLogIn.FormLogIn.Password + "," + Rtl.IntToStr(About.AboutBox.Major) + "," + Rtl.IntToStr(About.AboutBox.Minor) + "," + Rtl.IntToStr(About.AboutBox.Release) + "," + Rtl.IntToStr(About.AboutBox.Build));
            fASCIISend.AppendStrings(fWHORUFile);
        }

        // Delphi: procedure TFormASCIITransfer.SendFile(const pPCFileName, pPanelFileName: string; const pErrors: tErrorList)
        public void SendFile(string pPCFileName, string pPanelFileName, TErrorList pErrors)
        {
            RetryCount = 0;
            fErrors = pErrors;
            fErrors.Clear();
            fPanel = 0;
            fCurrPanel = null;
            CheckForDevices();
            fASCIIExtraInfo.UseWaitForSingleObject = UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Check_USB_Status);
            fASCIIExtraInfo.UseThreading = UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Use_Threading);
            fRecCount = 0;
            SetupVisualInterfaceSimple();
            if (!UnitPanelLogIn.FormLogIn.Execute())
            {
                return;
            }
            AbortButtonVisible = false;
            Rtl.SetVisible(LabelRecords, false);
            Rtl.SetVisible(LabelProgress, false);
            SendFile2(pPCFileName, pPanelFileName, pErrors);
            if (fErrors.ErrorCount == 0 || UnitExpertModes.ErrorReportingLevel == TErrorReportingLevel.el_None)
            {
                Rtl.ShowModal(this);
                return;
            }
            throw new ExceptionZFPErrors(TExceptionZFPErrorsFailMode.fm_Transfer);
        }

